"""Transparent asynchronous HTTP reverse proxy."""

from __future__ import annotations

import math
from collections.abc import AsyncIterable, Sequence
from typing import Final
from urllib.parse import quote, unquote

import httpx

from ..registry import provider
from .base import BaseProxyComponent, ProxyError, ProxyResponse

# These headers describe one transport hop and must be regenerated by httpx or
# Starlette. ``host`` is owned by the selected upstream.
_HOP_BY_HOP_HEADERS: Final = frozenset(
    {
        "connection",
        "host",
        "keep-alive",
        "proxy-authenticate",
        "proxy-authorization",
        "te",
        "trailer",
        "transfer-encoding",
        "upgrade",
    }
)


def _forward_headers(headers: Sequence[tuple[str, str]], *, decoded: bool = False) -> tuple[tuple[str, str], ...]:
    """Preserve repeated end-to-end headers and remove connection-owned fields."""
    excluded = _HOP_BY_HOP_HEADERS | {
        item.strip().lower()
        for key, value in headers
        if key.lower() == "connection"
        for item in value.split(",")
        if item.strip()
    }
    if decoded:
        # httpx decodes response bodies, so their encoded size and encoding are obsolete.
        excluded |= {"content-encoding", "content-length"}
    return tuple((key, value) for key, value in headers if key.lower() not in excluded)


def _request_url(base_url: httpx.URL, path: str) -> httpx.URL:
    """Encode a routed path and append it within the configured upstream prefix."""
    if path and (
        path.startswith("/")
        or not httpx.URL(path).is_relative_url
        or any(part in {".", ".."} for part in unquote(path).split("/"))
    ):
        raise ProxyError("Invalid proxy request path", status_code=422)
    return base_url.copy_with(raw_path=base_url.raw_path + quote(path, safe="/").encode("ascii"))


@provider("http")
class HttpProxyComponent(BaseProxyComponent):
    """Forward streaming HTTP requests to one fixed upstream base URL."""

    def __init__(
        self,
        upstream_base_url: str,
        timeout: float = 600,
        transport: httpx.AsyncBaseTransport | None = None,
        **kwargs,
    ) -> None:
        super().__init__(**kwargs)
        if not isinstance(upstream_base_url, str) or not upstream_base_url.strip():
            raise ValueError("Proxy upstream_base_url must not be empty")
        if not math.isfinite(timeout) or timeout <= 0:
            raise ValueError("Proxy timeout must be finite and greater than 0")

        base_url = upstream_base_url.rstrip("/")
        try:
            parsed = httpx.URL(base_url)
        except httpx.InvalidURL as exc:
            raise ValueError("Proxy upstream_base_url must be an HTTP(S) URL") from exc
        if parsed.scheme not in {"http", "https"} or not parsed.host:
            raise ValueError("Proxy upstream_base_url must be an HTTP(S) URL")
        if "?" in base_url or "#" in base_url:
            raise ValueError("Proxy upstream_base_url cannot contain a query or fragment")

        self.upstream_base_url = base_url
        self.timeout = timeout
        self._transport = transport
        self._client: httpx.AsyncClient | None = None

    async def _start(self) -> None:
        self._client = httpx.AsyncClient(
            base_url=f"{self.upstream_base_url}/",
            timeout=self.timeout,
            transport=self._transport,
        )

    async def _close(self) -> None:
        client, self._client = self._client, None
        if client is not None:
            await client.aclose()

    async def forward(
        self,
        method: str,
        path: str,
        *,
        query: Sequence[tuple[str, str]] = (),
        headers: Sequence[tuple[str, str]] = (),
        content: bytes | AsyncIterable[bytes] = b"",
    ) -> ProxyResponse:
        """Forward method, path, query, end-to-end headers, and body unchanged."""
        client = self._client
        if client is None:
            raise RuntimeError("Proxy component is not running")

        try:
            # Explicit requests reuse the connection pool without inheriting the
            # client's cookie jar or adding its default end-to-end headers.
            request = httpx.Request(
                method,
                _request_url(client.base_url, path),
                params=query,
                headers=_forward_headers(headers),
                content=content,
            )
            response = await client.send(request, stream=True)
        except httpx.InvalidURL as exc:
            raise ProxyError("Invalid proxy request path", status_code=422) from exc
        except httpx.TimeoutException as exc:
            raise ProxyError(f"Proxy upstream timed out: {self.upstream_base_url}", status_code=504) from exc
        except httpx.HTTPError as exc:
            self.logger.warning(f"Proxy upstream request failed: {exc}")
            raise ProxyError("Proxy upstream request failed") from exc

        return ProxyResponse(
            status_code=response.status_code,
            content=response.aiter_bytes(),
            headers=_forward_headers(response.headers.multi_items(), decoded=True),
            close=response.aclose,
        )
